export const translateTextValue = (value: string, language: 'id' | 'en') => {
  if (language === 'id') return value;
  const directTranslation = EN_TEXT[value] || PRODUCT_EN_TEXT[value];
  if (directTranslation) return directTranslation;

  const trimmedValue = value.trim();
  if (trimmedValue !== value) {
    return EN_TEXT[trimmedValue] || PRODUCT_EN_TEXT[trimmedValue] || value;
  }

  return value;
};
